82	int iforce_control_playback(struct iforce* iforce, u16 id, unsigned int value)
83	{
84		unsigned char data[3];
85	
86		data[0] = LO(id);
87		data[1] = (value > 0) ? ((value > 1) ? 0x41 : 0x01) : 0;
88		data[2] = LO(value);
89		return iforce_send_packet(iforce, FF_CMD_PLAY, data);
